window.ORACLE={"archetypes": [{"id": 0, "name": "L'Aventurier", "image": "assets/tarot/0.jpg"}, {"id": 1, "name": "Le Créateur", "image": "assets/tarot/01.jpg"}, {"id": 2, "name": "Le Mentor", "image": "assets/tarot/02.jpg"}, {"id": 3, "name": "Le Martyr", "image": "assets/tarot/03.jpg"}, {"id": 4, "name": "Le Chef", "image": "assets/tarot/04.jpg"}, {"id": 5, "name": "Le Chercheur", "image": "assets/tarot/05.jpg"}, {"id": 6, "name": "Le Soigneur", "image": "assets/tarot/06.jpg"}, {"id": 7, "name": "Le Traditionaliste", "image": "assets/tarot/07.jpg"}, {"id": 8, "name": "Le Médiateur", "image": "assets/tarot/08.jpg"}, {"id": 9, "name": "L'Ermite", "image": "assets/tarot/09.jpg"}, {"id": 10, "name": "L'Hérétique", "image": "assets/tarot/10.jpg"}, {"id": 11, "name": "Le Conquérant", "image": "assets/tarot/11.jpg"}, {"id": 12, "name": "L'Abomination", "image": "assets/tarot/12.jpg"}, {"id": 13, "name": "Le Destructeur", "image": "assets/tarot/13.jpg"}, {"id": 14, "name": "L'Élu", "image": "assets/tarot/14.jpg"}, {"id": 15, "name": "Le Profanateur", "image": "assets/tarot/15.jpg"}, {"id": 16, "name": "Le Protecteur", "image": "assets/tarot/16.jpg"}, {"id": 17, "name": "Le Visionnaire", "image": "assets/tarot/17.jpg"}, {"id": 18, "name": "Le Fanatique", "image": "assets/tarot/18.jpg"}, {"id": 19, "name": "Le Disciple", "image": "assets/tarot/19.jpg"}, {"id": 20, "name": "Le Vertueux", "image": "assets/tarot/20.jpg"}, {"id": 21, "name": "Le Voyageur", "image": "assets/tarot/21.jpg"}], "combinations": {"L'Aventurier": {"Le Créateur": "L'Innovation Risquée. Vous devez sortir des sentiers battus pour réaliser votre œuvre. L'audace est la seule façon de bâtir quelque chose qui durera.", "Le Mentor": "L'Apprentissage par l'Expérience. La théorie ne suffit plus ; il faut se jeter dans l'inconnu pour apprendre. Le maître pousse l'élève hors du nid pour qu'il teste ses limites.", "Le Martyr": "Le Sacrifice Héroïque. Se mettre en danger pour autrui. Prendre un risque mortel non pour le frisson, mais pour sauver ceux qui ne peuvent se défendre.", "Le Chef": "La Conquête du Chaos. L'envie d'explorer se heurte au besoin de contrôle. Peut signifier prendre la tête d'une expédition ou devoir canaliser sa fougue pour diriger efficacement.", "Le Chercheur": "L'Expédition Scientifique. La curiosité devient obsessionnelle. Aller là où personne n'est allé pour trouver une vérité cachée, quitte à y laisser sa peau.", "Le Soigneur": "Le Sauvetage Désespéré. Braver le danger pour apporter un remède. Ou bien, la nécessité de réparer les dégâts causés par une imprudence passée.", "Le Traditionaliste": "Le Choc des Générations. Conflit entre l'appel de l'aventure et la sécurité du foyer. Briser les règles établies pour prouver qu'une autre voie est possible.", "Le Médiateur": "L'Ambassadeur Audacieux. Tenter une approche diplomatique risquée. Aller à la rencontre de l'ennemi ou de l'inconnu pour établir un lien improbable.", "L'Ermite": "La Traversée du Désert. Une aventure intérieure ou solitaire. S'éloigner de tout pour se tester soi-même, sans public ni gloire.", "L'Hérétique": "La Rébellion Totale. Le goût du risque se met au service de la destruction de l'ordre établi. Enfreindre les interdits juste pour voir ce qui se passera.", "Le Conquérant": "La Gloire ou la Mort. L'ambition démesurée. Chercher l'exploit ultime pour nourrir son ego et écraser toute concurrence.", "L'Abomination": "La Descente aux Enfers. La curiosité mène à l'horreur. Explorer ce qui aurait dû rester caché et en revenir (ou non) brisé par la peur.", "Le Destructeur": "La Terre Brûlée. Une fuite en avant qui laisse le chaos derrière soi. Détruire pour le plaisir du changement radical, sans se soucier des conséquences.", "L'Élu": "La Quête du Graal. Se sentir investi d'une mission divine qui justifie tous les dangers. L'aventure devient un pèlerinage ou une croisade personnelle.", "Le Profanateur": "Le Sabotage. Prendre des risques pour nuire aux autres. L'envie de gâcher la fête ou de voler le trésor juste pour que personne d'autre ne l'ait.", "Le Protecteur": "Le Gardien de la Frontière. Patrouiller dans les zones dangereuses pour protéger le groupe. Le risque est pris pour créer un périmètre de sécurité.", "Le Visionnaire": "Le Pionnier. Marcher vers un avenir que l'on est le seul à voir. Ouvrir la voie, non par caprice, mais parce que le destin de l'humanité en dépend.", "Le Fanatique": "La Croisade Aveugle. Repousser ses limites par ferveur religieuse. Aucune montagne n'est trop haute pour prouver sa foi, même si cela signifie la mort.", "Le Disciple": "Le Voyage Initiatique. Partir à l'aventure pour apprendre. Suivre les traces d'un maître dans des contrées sauvages pour accumuler du savoir.", "Le Vertueux": "Le Jugement Expéditif. Imposer sa morale dans les zones de non-droit. L'Aventurier se fait justicier errant, appliquant ses propres lois loin de la civilisation.", "Le Voyageur": "L'Errance Éternelle. Le mouvement perpétuel. L'incapacité totale à se poser. Une vie passée sur la route, reliant les mondes sans jamais appartenir à aucun."}, "Le Créateur": {"L'Aventurier": "L'Expérimentation. Le Créateur sort de son atelier pour tester son invention sur le terrain. L'idée ne vaut rien si elle ne survit pas à l'épreuve du monde réel.", "Le Mentor": "La Maîtrise. La relation Maître-Artisan. Le Créateur n'invente pas seul ; il perfectionne un savoir-faire transmis par un ancien pour atteindre l'excellence.", "Le Martyr": "Le Grand Œuvre. Se tuer à la tâche. Donner sa vie ou sa santé pour achever une création qui survivra à son auteur. L'art exige des sacrifices.", "Le Chef": "L'Architecte d'Empire. La construction au service du pouvoir. Bâtir des infrastructures, des villes ou des organisations structurées pour asseoir une autorité.", "Le Chercheur": "L'Ingénierie. L'alliance de la théorie et de la pratique. Percer les mystères de la matière pour inventer une technologie nouvelle ou redécouvrir un procédé perdu.", "Le Soigneur": "La Reconstruction. Bâtir pour réparer. Créer des prothèses, reconstruire un refuge détruit ou concevoir des outils médicaux. L'ingéniosité au service de la vie.", "Le Traditionaliste": "La Restauration. Préserver le patrimoine. Le Créateur met son talent au service du passé, consolidant les fondations anciennes plutôt que d'innover à tout prix.", "Le Médiateur": "Le Pont. Bâtir des liens tangibles. Créer des espaces de rencontre, des routes commerciales ou des accords concrets qui unissent les communautés.", "L'Ermite": "L'Atelier Secret. L'inventeur solitaire qui travaille loin du monde. Une création géniale qui mûrit dans l'ombre, incomprise ou cachée de tous.", "L'Hérétique": "L'Art Subversif. Créer pour choquer ou déstabiliser. Une invention qui remet en cause l'ordre établi ou une œuvre qui brise les tabous moraux.", "Le Conquérant": "La Machine de Guerre. L'industrie de l'armement. Forger des épées, construire des fortifications ou des engins de siège pour permettre l'expansion territoriale.", "L'Abomination": "Le Monstre de Frankenstein. L'orgueil créateur qui vire au cauchemar. Une invention qui échappe à son contrôle ou une création contre-nature.", "Le Destructeur": "Le Cycle Éternel. Faire table rase pour reconstruire. Il faut abattre les vieilles ruines pour bâtir du neuf. Ou la frustration de voir son œuvre anéantie.", "L'Élu": "Le Monument. Bâtir un symbole. Une statue, un temple ou un trône destiné à glorifier une figure messianique. La pierre au service du mythe.", "Le Profanateur": "Le Plagiat. Le vol d'idées. Quelqu'un s'approprie le travail du Créateur, ou le Créateur sabote l'œuvre d'un rival par jalousie.", "Le Protecteur": "La Forteresse. L'ingéniosité défensive. Concevoir des pièges, des murs imprenables ou des systèmes de sécurité pour protéger ce qui est précieux.", "Le Visionnaire": "L'Utopie. Concevoir la cité du futur. Le Créateur donne forme aux rêves du Visionnaire. Un projet grandiose, peut-être irréalisable, mais inspirant.", "Le Fanatique": "La Relique. L'objet de culte. Fabriquer des idoles ou des armes sacrées. La créativité est bridée par le dogme mais exaltée par la foi.", "Le Disciple": "La Succession. Former un apprenti. Le Créateur se préoccupe de qui reprendra ses outils et son œuvre après sa mort. Assurer la pérennité du savoir.", "Le Vertueux": "La Rigueur. L'architecture stricte. Construire selon des codes précis, sans fioritures. Des prisons, des tribunaux, des lieux fonctionnels et austères.", "Le Voyageur": "Le Véhicule. Créer pour bouger. Inventer des moyens de transport, des cartes ou des équipements de survie mobiles. L'atelier nomade."}, "Le Mentor": {"L'Aventurier": "La Préparation. Avant de partir, il faut apprendre. Le Mentor tempère la fougue de l'Aventurier par la prudence et l'expérience. \"N'y va pas sans cette carte.\"", "Le Créateur": "Le Maître Artisan. L'alliance du savoir-faire ancien et de la construction nouvelle. Le Mentor guide la main du Créateur pour qu'il ne répète pas les erreurs du passé.", "Le Martyr": "Le Fardeau de la Responsabilité. Apprendre à souffrir pour les autres. Le Mentor enseigne que le véritable leadership exige le sacrifice de soi. Une leçon douloureuse mais nécessaire.", "Le Chef": "L'Éminence Grise. Le pouvoir derrière le trône. Le Chef commande, mais c'est le Mentor qui lui murmure la stratégie à l'oreille. Le conseiller indispensable.", "Le Chercheur": "L'Académie. Le savoir institutionnel face à la recherche pure. Le conflit ou l'alliance entre ce qui est connu (Mentor) et ce qui reste à découvrir (Chercheur).", "Le Soigneur": "Le Serment d'Hippocrate. La transmission des secrets de la vie et de la mort. Former la prochaine génération de médecins pour que l'humanité survive.", "Le Traditionaliste": "Le Gardien du Dogme. Une alliance conservatrice puissante. Le savoir est verrouillé, les coutumes sont lois. Le changement est perçu comme une menace à éradiquer.", "Le Médiateur": "Le Conseil des Sages. La résolution des conflits par l'expérience. On fait appel aux anciens pour juger un litige, car ils ont déjà tout vu.", "L'Ermite": "Le Savoir Perdu. Le Mentor qui s'est retiré du monde. Pour apprendre, il faut aller le chercher au sommet de la montagne. Une connaissance qui se mérite par l'isolement.", "L'Hérétique": "Le Mauvais Berger. Un enseignement qui corrompt. Le Mentor utilise son autorité pour semer le doute ou propager des idées dangereuses qui brisent les tabous.", "Le Conquérant": "Le Stratège. Enseigner l'art de la guerre. Le Mentor ne se bat pas, mais il forme celui qui remportera la victoire. La sagesse au service de l'ambition.", "L'Abomination": "La Leçon Interdite. Étudier ce qu'il ne faut pas. Le Mentor détient des connaissances sur les monstres ou la corruption, risquant de contaminer ses élèves.", "Le Destructeur": "La Fin de l'Enseignement. L'élève dépasse le maître et le tue (symboliquement ou réellement). Ou bien la prise de conscience que tout savoir est vain face à l'anéantissement inévitable.", "L'Élu": "Le Faiseur de Rois. Le Mentor reconnait le potentiel divin ou exceptionnel chez un individu et consacre sa vie à le préparer pour son destin. (Ex: Merlin et Arthur).", "Le Profanateur": "La Rétention du Savoir. Le Mentor refuse de partager ses secrets par jalousie ou peur d'être dépassé. Il humilie l'élève pour garder le dessus.", "Le Protecteur": "La Garde de la Bibliothèque. Protéger le savoir physiquement. Le Mentor et le Protecteur s'allient pour que les livres ou les traditions ne brûlent pas.", "Le Visionnaire": "L'Héritage Futur. Le Mentor transmet le passé pour que le Visionnaire puisse construire l'avenir. Le passage de témoin entre l'histoire et le progrès.", "Le Fanatique": "Le Gourou. L'enseignement devient endoctrinement. Le Mentor ne veut pas des élèves qui réfléchissent, mais des fidèles qui obéissent aveuglément.", "Le Disciple": "La Transmission Parfaite. L'alignement idéal. Le savoir coule de l'un à l'autre sans obstacle. La relation symbiotique qui assure la survie de la connaissance.", "Le Vertueux": "La Discipline de Fer. L'éducation à la dure. Apprendre par la rigueur, la punition et le respect absolu des règles morales. Aucune déviation n'est tolérée.", "Le Voyageur": "Le Maître Itinérant. La sagesse qui se déplace. Le Mentor n'a pas d'école fixe ; il enseigne sur la route, semant des graines de savoir dans chaque communauté traversée."}, "Le Martyr": {"L'Aventurier": "Le Risque Altruiste. Se mettre en danger non pour l'adrénaline, mais pour faire écran. L'Aventurier ouvre la voie, le Martyr encaisse les coups.", "Le Créateur": "L'Œuvre de Sang. L'art demande des sacrifices. Le Martyr donne sa force vitale pour que le Créateur puisse achever son chef-d'œuvre.", "Le Mentor": "L'Exemple Douloureux. Enseigner par le sacrifice. Le Martyr montre la voie en endurant la souffrance, une leçon muette mais puissante pour ses élèves.", "Le Chef": "Le Bouc Émissaire. Le Chef prend la décision difficile, le Martyr en paie le prix pour le bien du groupe. Assumer la faute pour maintenir l'ordre.", "Le Chercheur": "Le Cobaye. Offrir son corps à la science. Accepter des expériences dangereuses ou douloureuses pour permettre au Chercheur de trouver un remède ou une vérité.", "Le Soigneur": "La Compassion Infinie. Le Martyr absorbe la douleur des autres, le Soigneur tente de le maintenir en vie. Un cycle d'épuisement et de restauration.", "Le Traditionaliste": "Le Gardien du Temple. Mourir pour ses traditions. Le refus absolu de céder, même face à l'extinction, pour préserver l'honneur du passé.", "Le Médiateur": "La Trêve. Se sacrifier pour la paix. Accepter une injustice ou perdre la face volontairement pour désamorcer un conflit violent.", "L'Ermite": "L'Ascète. La privation volontaire. Se retirer du monde pour souffrir en silence, loin des regards, purifiant son âme par la solitude et la faim.", "L'Hérétique": "Le Martyr de la Révolution. Mourir pour une cause impopulaire. Être persécuté par l'ordre établi parce qu'on a osé dire une vérité qui dérange.", "Le Conquérant": "La Chair à Canon. La victoire se bâtit sur les cadavres des dévoués. Le Martyr est le soldat qui tient la ligne jusqu'au bout pour que son camp gagne.", "L'Abomination": "L'Offrande. Se livrer au monstre pour rassasier sa faim et sauver les autres. Un pacte terrifiant où l'un paie pour la survie de tous.", "Le Destructeur": "Le Sacrifice Vain. Donner sa vie face à une force inarrêtable. La noblesse du geste face à l'absurdité de la destruction totale.", "L'Élu": "Le Prophète Souffrant. La douleur est la preuve de l'élection divine. Les stigmates. Inspirer les foules non par la force, mais par l'endurance.", "Le Profanateur": "La Victime. Le sacrifice est moqué ou volé. Le Profanateur profite de la bonté du Martyr pour l'exploiter sans vergogne.", "Le Protecteur": "Le Bouclier Humain. L'alliance défensive ultime. L'un protège activement, l'autre absorbe passivement les dégâts qui passent la garde.", "Le Visionnaire": "Le Prix du Futur. Accepter que sa génération souffre et se sacrifie pour que les enfants de demain connaissent un monde meilleur.", "Le Fanatique": "Le Kamikaze. Le sacrifice offensif. Donner sa vie comme une arme pour détruire l'ennemi de la foi. L'abnégation devient violence.", "Le Disciple": "Le Fidèle Serviteur. Dévouer sa vie à l'ascension d'un autre. Le Martyr s'efface pour que le Disciple puisse briller et apprendre.", "Le Vertueux": "La Pénitence. Souffrir pour expier ses fautes ou celles du monde. Le jugement moral impose une punition que le Martyr accepte volontiers.", "Le Voyageur": "Le Pèlerinage. Une marche harassante. Supporter la fatigue, la faim et les éléments sur la route pour atteindre un lieu saint ou un but lointain."}, "Le Chef": {"L'Aventurier": "L'Expédition. Le Chef canalise l'énergie de l'Aventurier. Il donne un but et une direction à la prise de risque, transformant l'errance en conquête.", "Le Créateur": "Le Bâtisseur d'Empire. Le pouvoir ordonne la construction. Utiliser les ressources de l'état ou du clan pour ériger des fortifications et des monuments.", "Le Mentor": "Le Conseil. Le Chef écoute avant d'agir. La sagesse du Mentor tempère l'ambition du Chef. Une gouvernance éclairée.", "Le Martyr": "Le Devoir. Exiger le sacrifice. Le Chef doit parfois envoyer ses hommes à la mort pour le bien commun, portant le poids de ces vies sur sa conscience.", "Le Chercheur": "Le Mécène. Le pouvoir au service du savoir. Le Chef finance ou protège les recherches, attendant en retour des armes ou des avantages stratégiques.", "Le Soigneur": "La Santé Publique. Gérer les ressources vitales. Décider qui reçoit les soins en priorité (triage) pour assurer la survie du groupe le plus large possible.", "Le Traditionaliste": "Le Conservateur. L'ordre par la tradition. Le Chef appuie son autorité sur les coutumes anciennes. \"On fait comme ça car on a toujours fait comme ça.\"", "Le Médiateur": "La Diplomatie. Le Chef délègue la parole pour éviter la guerre. Négocier des alliances et des traités plutôt que d'utiliser la force brute.", "L'Ermite": "L'Exil. Le Chef bannit l'indésirable, ou le Chef se retrouve isolé au sommet, coupé de la réalité de son peuple par le protocole.", "L'Hérétique": "La Guerre Civile. L'autorité contestée. Le Chef doit écraser la rébellion ou être renversé. Le conflit entre l'ordre et la liberté.", "Le Conquérant": "L'Empereur. L'alliance de l'administration et de la guerre. Expansion territoriale agressive gérée d'une main de fer. L'ambition sans limites.", "L'Abomination": "Le Tyran Fou. Le pouvoir corrompu par l'horreur. Un Chef qui règne par la terreur absolue, ou qui utilise des monstres pour garder le contrôle.", "Le Destructeur": "La Purge. Le Chef ordonne l'élimination systématique d'une menace. Utiliser la force brute pour nettoyer les rangs, quitte à affaiblir le groupe.", "L'Élu": "Le Roi-Dieu. Le pouvoir politique fusionne avec le pouvoir spirituel. Le Chef n'est pas seulement obéi, il est vénéré. Le culte de la personnalité.", "Le Profanateur": "La Corruption. Un leadership pourri de l'intérieur. Le Chef abuse de son pouvoir pour s'enrichir, humilier ses rivaux et satisfaire ses vices.", "Le Protecteur": "La Loi Martiale. L'ordre sécuritaire. Le Chef restreint les libertés pour garantir la sécurité totale. Un régime policier mais sûr.", "Le Visionnaire": "Le Réformateur. Un Chef qui regarde vers l'avenir. Prêt à changer les lois et bousculer les habitudes pour préparer son peuple aux défis de demain.", "Le Fanatique": "L'Inquisiteur. Le pouvoir au service du dogme. Le Chef traque les ennemis de la foi avec les ressources de l'état. L'intolérance institutionnalisée.", "Le Disciple": "Le Successeur. La formation de l'héritier. Le Chef prépare celui qui prendra sa place, lui inculquant la rudesse du commandement.", "Le Vertueux": "Le Juge. L'autorité morale. Le Chef tranche les litiges avec une rigueur inflexible. La loi est dure, mais c'est la loi.", "Le Voyageur": "Le Chef de Caravane. Une autorité mobile. Diriger un groupe nomade où la survie dépend de la cohésion et de la capacité à s'adapter au terrain."}, "Le Chercheur": {"L'Aventurier": "L'Exploration. Aller chercher les données sur le terrain. Le Chercheur quitte son labo pour vérifier ses hypothèses dans les ruines dangereuses.", "Le Créateur": "L'Invention. La découverte théorique devient application pratique. Comprendre comment marche l'électricité pour construire un générateur.", "Le Mentor": "L'Erudition. La compilation du savoir. Le Chercheur s'appuie sur les bibliothèques et les enseignements des anciens pour avancer.", "Le Martyr": "Le Prix de la Connaissance. Savoir demande des sacrifices. S'exposer aux radiations ou aux toxines pour comprendre leur fonctionnement.", "Le Chef": "Le Conseiller Technique. La vérité au service du pouvoir. Fournir des informations cruciales aux dirigeants pour qu'ils prennent les bonnes décisions.", "Le Soigneur": "La Pathologie. Comprendre la maladie pour la guérir. L'étude des virus, des spores ou des mutations pour développer des antidotes.", "Le Traditionaliste": "L'Archéologie. Étudier le passé pour le comprendre, non pour le vénérer aveuglément. Conflit entre la vérité historique et le mythe traditionnel.", "Le Médiateur": "La Compréhension. Analyser les cultures ou les langues pour faciliter la communication. Savoir pourquoi l'autre agit ainsi pour mieux négocier.", "L'Ermite": "Le Secret. Une découverte gardée pour soi. Le Chercheur trouve quelque chose de trop dangereux pour être partagé et le cache au monde.", "L'Hérétique": "La Vérité Interdite. Découvrir des faits qui contredisent le dogme officiel. Le Chercheur devient un ennemi public parce qu'il a raison.", "Le Conquérant": "L'Espionnage. La recherche d'informations sur l'ennemi. Connaître les faiblesses de l'adversaire pour mieux l'écraser. Le savoir est une arme.", "L'Abomination": "La Vivisection. L'étude du monstrueux. Disséquer l'horreur pour comprendre son anatomie, au risque de perdre sa santé mentale.", "Le Destructeur": "L'Arme Ultime. Chercher le moyen le plus efficace de tout raser. La science mise au service de l'anéantissement (bombe, poison, etc.).", "L'Élu": "La Preuve Divine. Chercher à expliquer rationnellement les miracles ou, à l'inverse, trouver la preuve scientifique d'une destinée supérieure.", "Le Profanateur": "La Science sans Conscience. L'expérimentation cruelle. Le Chercheur ignore l'éthique pour obtenir des résultats, manipulant la vie sans respect.", "Le Protecteur": "La Surveillance. Utiliser la technologie ou l'observation pour détecter les menaces avant qu'elles n'arrivent. Le savoir comme bouclier.", "Le Visionnaire": "La Théorie. Imaginer ce qui n'existe pas encore. Le Chercheur fournit les faits, le Visionnaire en tire un plan pour le futur.", "Le Fanatique": "Le Dogmatisme. Refuser les faits qui ne collent pas à la croyance. Le conflit violent entre la foi aveugle et la preuve scientifique.", "Le Disciple": "La Recherche Fondamentale. La quête de savoir pour le savoir. Accumuler des données sans but immédiat, juste pour repousser l'ignorance.", "Le Vertueux": "L'Éthique. Poser des limites morales à la science. \"Nous pouvons le faire, mais devons-nous le faire ?\" Le jugement sur la découverte.", "Le Voyageur": "Le Cartographe. Découvrir le monde physique. Tracer les cartes, noter la faune et la flore, comprendre la géographie du nouveau monde."}, "Le Soigneur": {"L'Aventurier": "Le Médecin de Terrain. Suivre l'action pour recoudre les blessés sur place. La médecine d'urgence dans des conditions extrêmes.", "Le Créateur": "La Prothèse. Réparer le corps avec la machine. L'alliance de la biologie et de la technologie pour rendre sa mobilité à un infirme.", "Le Mentor": "L'Enseignement Médical. Transmettre les gestes qui sauvent. Former la communauté aux premiers secours pour augmenter l'autonomie du groupe.", "Le Martyr": "Le Don de Soi. S'épuiser à soigner les autres. Le Soigneur prend sur lui la charge émotionnelle et physique de la souffrance d'autrui.", "Le Chef": "Le Triage. Décision froide. Choisir qui sauver et qui abandonner faute de ressources, sous l'autorité du Chef ou pour le bien du groupe.", "Le Chercheur": "Le Remède. L'analyse des symptômes pour trouver la cure. Diagnostiquer un mal inconnu ou une nouvelle infection du Sepsis.", "Le Traditionaliste": "La Médecine Ancienne. Utiliser les plantes, les vieux remèdes et les techniques ancestrales plutôt que la technologie moderne ou risquée.", "Le Médiateur": "La Guérison Sociale. Soigner les relations autant que les corps. Apaiser les esprits traumatisés pour rétablir l'harmonie dans le groupe.", "L'Ermite": "L'Automédication. Se soigner seul, ou soigner quelqu'un en secret, loin de la société. Une guérison qui demande du calme et de l'isolement.", "L'Hérétique": "L'Avorteur / Le Bio-Hacker. Pratiquer une médecine interdite ou taboue. Modifier le corps ou soigner les ennemis du clan par éthique personnelle.", "Le Conquérant": "Le Maintien des Troupes. Soigner pour que les soldats puissent retourner au combat. La médecine comme outil logistique de la guerre.", "L'Abomination": "La Mutation. Tenter de soigner l'incurable. Faire face à la corruption génétique. Le soin échoue ou transforme le patient en monstre.", "Le Destructeur": "L'Euthanasie. La guérison est impossible, la seule compassion restante est de donner une mort douce. La fin de la souffrance par la mort.", "L'Élu": "Le Miracle. Une guérison inexpliquée, quasi magique. Le charisme du Soigneur ou la foi du patient provoque une rémission impossible.", "Le Profanateur": "L'Empoisonneur. Connaître l'anatomie pour nuire. Le Soigneur inversé : administrer des toxines ou prolonger la souffrance volontairement.", "Le Protecteur": "La Quarantaine. Isoler les malades pour protéger les sains. Une mesure de soin préventive mais sévère pour la sécurité de tous.", "Le Visionnaire": "L'Eugénisme / L'Amélioration. Vouloir \"guérir\" l'humanité de ses faiblesses pour créer un homme nouveau, plus fort et résistant.", "Le Fanatique": "La Purification. Soigner l'âme par la douleur. Considérer la maladie comme une punition divine qu'il faut expier avant de guérir.", "Le Disciple": "L'Interne. L'assistant du médecin. Apprendre l'art complexe de la guérison en observant et en aidant, humblement.", "Le Vertueux": "Le Soin Sélectif. Ne soigner que ceux qui le \"méritent\". Refuser l'aide aux criminels ou aux ennemis par principe moral strict.", "Le Voyageur": "Le Médecin Errant. Aller de village en village pour offrir ses services. Apporter des médicaments d'ailleurs et des nouvelles."}, "Le Traditionaliste": {"L'Aventurier": "Le Rappel à l'Ordre. L'Aventurier veut partir, le Traditionaliste lui rappelle ses devoirs envers le foyer. Le conflit entre l'appel du large et les racines.", "Le Créateur": "L'Artisanat Ancestral. Rejeter les nouvelles technologies pour privilégier les méthodes éprouvées. Faire les choses \"comme avant\", solidement.", "Le Mentor": "L'Histoire. Transmettre non pas des compétences, mais l'identité du clan. Les légendes, les mythes fondateurs et les erreurs à ne pas répéter.", "Le Martyr": "La Loyauté. Rester fidèle à une cause perdue ou ancienne par honneur. Mourir pour un drapeau qui n'existe plus.", "Le Chef": "La Légitimité. Le pouvoir justifié par le sang ou la lignée. Le Traditionaliste soutient le Chef parce qu'il est l'héritier légitime des anciens.", "Le Chercheur": "L'Obscurantisme. Le refus de savoir. Certaines portes doivent rester fermées. Le Traditionaliste s'oppose aux découvertes qui menacent les croyances.", "Le Soigneur": "Le Remède de Grand-Mère. Méfiance envers la médecine moderne ou étrangère. On se soigne avec les herbes et les rituels du clan.", "Le Médiateur": "Le Conseil des Anciens. Utiliser les vieilles alliances pour régler les conflits actuels. \"Nos pères ont fait la paix, nous devons la respecter.\"", "L'Ermite": "Le Gardien des Ruines. Vivre seul au milieu des vestiges du passé, veillant sur un lieu ou un objet oublié de tous.", "L'Hérétique": "L'Anathème. Le conflit total. Le Traditionaliste ne tolère pas la déviance. L'Hérétique doit être banni ou puni pour avoir brisé les tabous.", "Le Conquérant": "La Reconquête. Vouloir rétablir les frontières d'antan. La guerre motivée par le désir de revenir à un âge d'or mythifié.", "L'Abomination": "La Malédiction Ancestrale. Un mal ancien qui revient hanter le présent. Le Traditionaliste savait que cela arriverait car les prophéties l'avaient dit.", "Le Destructeur": "La Fin d'une Époque. Voir ses traditions anéanties. La douleur de voir les lieux sacrés ou les coutumes détruits à jamais.", "L'Élu": "Le Retour du Roi. Voir en quelqu'un la réincarnation d'un héros passé. L'attente messianique basée sur de vieilles légendes.", "Le Profanateur": "Le Pillage. Le non-respect des sites sacrés. Le Profanateur souille ce que le Traditionaliste vénère. Un sacrilège impardonnable.", "Le Protecteur": "La Sentinelle. Veiller sur le patrimoine. Protéger les reliques, les enfants ou les terres du clan contre toute influence extérieure.", "Le Visionnaire": "Le Conflit Temporel. Le passé contre le futur. Le Traditionaliste freine le Visionnaire, craignant que le progrès ne détruise l'âme du peuple.", "Le Fanatique": "L'Intégrisme. La tradition poussée à l'extrême. Respecter la lettre de la loi ancienne sans aucune pitié ni adaptation.", "Le Disciple": "L'Initiation. Le passage de l'âge adulte. Le Traditionaliste guide le Disciple à travers les rites de passage obligatoires pour intégrer la tribu.", "Le Vertueux": "Le Code d'Honneur. Une morale stricte issue du passé. On ne juge pas selon la situation, mais selon les règles immuables des ancêtres.", "Le Voyageur": "Le Nomadisme Traditionnel. Suivre les anciennes routes migratoires. On ne voyage pas au hasard, on suit le chemin tracé par les aïeux."}, "Le Médiateur": {"L'Aventurier": "L'Émissaire. Porter un message de paix en territoire inconnu ou hostile. Le voyage a pour but de relier deux mondes.", "Le Créateur": "Le Contrat. Négocier les ressources pour un projet. L'accord commercial qui permet à la construction de se faire.", "Le Mentor": "La Sagesse Partagée. Réunir des écoles de pensée différentes. Le Médiateur permet à deux savoirs distincts de dialoguer pour s'enrichir.", "Le Martyr": "La Concession. Pour obtenir la paix, il faut renoncer à quelque chose de précieux. Le compromis douloureux mais nécessaire.", "Le Chef": "Le Porte-Parole. Le visage aimable du pouvoir. Le Chef décide, le Médiateur explique et fait accepter la décision au peuple.", "Le Chercheur": "L'Échange de Données. La collaboration scientifique. Faire tomber les barrières du secret pour avancer ensemble vers la vérité.", "Le Soigneur": "La Réconciliation. Guérir les plaies de l'âme après un conflit. Le Médiateur apaise la colère, le Soigneur répare les corps.", "Le Traditionaliste": "Le Respect des Coutumes. Naviguer entre les tabous pour ne froisser personne. La diplomatie protocolaire et stricte.", "L'Ermite": "L'Intermédiaire. Le seul lien entre le monde et celui qui s'en est retiré. Aller chercher l'exilé pour le ramener dans le cercle.", "L'Hérétique": "L'Avocat du Diable. Tenter de comprendre le rebelle ou l'ennemi. Chercher un terrain d'entente avec ceux que la société rejette.", "Le Conquérant": "La Capitulation / Le Traité. La fin de la guerre par les mots. Négocier les termes de la reddition ou de la victoire pour éviter le massacre final.", "L'Abomination": "Le Pacte avec la Bête. Négocier l'impossible. Tenter de raisonner ou d'apaiser une force monstrueuse ou folle. Danger extrême.", "Le Destructeur": "L'Échec de la Diplomatie. Les mots ne suffisent plus. Le Médiateur se tait quand les armes parlent. Ou tenter de négocier face à l'apocalypse.", "L'Élu": "L'Apôtre. Répandre la bonne parole. Le Médiateur traduit la vision divine de l'Élu pour qu'elle soit comprise par le commun des mortels.", "Le Profanateur": "La Trahison / Le Double Jeu. Un accord vicié dès le départ. Le Médiateur manipule les deux camps pour semer la discorde sous couvert de paix.", "Le Protecteur": "La Zone Neutre. Créer un espace sûr où les ennemis peuvent se rencontrer sans armes. Garantir la sécurité des pourparlers.", "Le Visionnaire": "La Fédération. Unir des forces disparates autour d'un projet commun pour l'avenir. Créer une alliance durable.", "Le Fanatique": "Le Convertisseur. La persuasion religieuse. Convaincre l'autre de rejoindre la foi, non par l'épée, mais par le verbe.", "Le Disciple": "Le Négociateur Novice. Apprendre l'art de l'écoute. Le Médiateur forme le Disciple à comprendre les deux sons de cloche.", "Le Vertueux": "L'Arbitrage. Trancher un litige de manière équitable. Le Médiateur écoute, le Vertueux juge. La justice restaurative.", "Le Voyageur": "Le Messager. Transmettre les nouvelles entre les communautés éloignées. Le lien vivant qui empêche l'isolement total."}, "L'Ermite": {"L'Aventurier": "Le Guide Sauvage. Celui qui connaît le terrain parce qu'il y vit seul. L'Ermite montre le chemin caché à l'Aventurier.", "Le Créateur": "L'Invention Oubliée. Une technologie ou une structure créée loin de la civilisation, découverte par hasard. Le génie incompris.", "Le Mentor": "Le Vieux Maître. Le sage au sommet de la montagne (archétype classique). Il détient un savoir que la société a perdu.", "Le Martyr": "Le Pénitent. S'isoler pour expier une faute terrible. Vivre dans la misère volontaire comme punition personnelle.", "Le Chef": "L'Autorité Rejetée. L'Ermite a fui le commandement ou a été banni par le Chef. Le conflit entre la société et l'individu.", "Le Chercheur": "L'Observatoire. Étudier les phénomènes naturels ou le Sepsis loin des interférences humaines. La science en milieu hostile.", "Le Soigneur": "Le Guérisseur Rebouteux. Celui qui vit dans les bois et connaît les herbes. Une médecine efficace mais étrange, loin des hôpitaux.", "Le Traditionaliste": "Le Dernier des Siens. Le survivant d'une culture éteinte. Il garde seul la mémoire d'un peuple disparu.", "Le Médiateur": "Le Retour. Tenter de ramener l'Ermite dans la société. La difficulté de réintégrer le groupe après une longue solitude.", "L'Hérétique": "Le Culte Secret. Se cacher pour pratiquer des rites interdits. L'Ermite est un paria parce qu'il refuse les dogmes dominants.", "Le Conquérant": "La Terrere Incognita. L'Ermite vit sur le territoire que le Conquérant veut envahir. Le choc entre la tranquillité et l'invasion.", "L'Abomination": "La Transformation. À force de vivre près du Sepsis ou de l'horreur, l'Ermite a changé. Il n'est plus tout à fait humain.", "Le Destructeur": "Le Survivant. Celui qui reste quand tout le reste a brûlé. L'Ermite est le témoin silencieux de la fin du monde.", "L'Élu": "La Révélation. Dieu parle dans le silence. C'est dans la solitude absolue que l'Ermite reçoit sa vision ou sa mission.", "Le Profanateur": "Le Voleur de Secret. Quelqu'un vient troubler la paix de l'Ermite pour lui dérober ce qu'il cache ou le tourmenter.", "Le Protecteur": "Le Gardien Caché. L'Ermite surveille une menace depuis l'ombre. Il protège le monde sans que le monde le sache.", "Le Visionnaire": "L'Oracle. On vient consulter l'Ermite pour connaître l'avenir, car son recul lui donne une perspective unique.", "Le Fanatique": "L'Excommunié. Chassé pour impiété. L'Ermite est la preuve vivante que l'on peut vivre sans le dogme, ce qui enrage le Fanatique.", "Le Disciple": "La Quête du Maître. Le Disciple part chercher l'Ermite pour apprendre. Le test de détermination.", "Le Vertueux": "Le Jugement Intérieur. L'Ermite a quitté le monde parce qu'il le trouvait corrompu. Il juge la société depuis sa retraite.", "Le Voyageur": "La Rencontre de Hasard. Deux solitaires se croisent. Un moment de partage autour d'un feu avant que chacun ne reprenne sa route."}, "L'Hérétique": {"L'Aventurier": "L'Hors-la-loi. Vivre en marge des règles, par goût du risque et de la liberté. Le bandit de grand chemin ou le pirate.", "Le Créateur": "L'Art Dégénéré. Créer des œuvres qui choquent la morale ou la religion. L'innovation qui est perçue comme un blasphème.", "Le Mentor": "Le Corrupteur. Enseigner des mensonges ou des vérités dangereuses. Détourner la jeunesse du \"droit chemin\".", "Le Martyr": "Le Bouc Émissaire. Être persécuté pour sa différence. L'Hérétique souffre pour avoir osé être lui-même.", "Le Chef": "Le Révolutionnaire. L'Hérétique veut renverser le Chef. Le conflit direct entre le pouvoir établi et l'insurrection.", "Le Chercheur": "La Vérité qui Dérange. Prouver que les dieux n'existent pas ou que l'histoire officielle est fausse. La science contre le dogme.", "Le Soigneur": "La Sorcellerie. Utiliser des méthodes de soin interdites (mutagènes, technologie des Anciens). Sauver des vies par des moyens impurs.", "Le Traditionaliste": "Le Conflit de Valeurs. L'opposition totale. Le Traditionaliste défend le passé, l'Hérétique veut le brûler pour avancer.", "Le Médiateur": "L'Agitateur. Utiliser les mots pour semer le trouble. La propagande, le discours séditieux qui divise la population.", "L'Ermite": "Le Paria. Rejeté par tous, l'Hérétique n'a d'autre choix que la solitude. L'exil forcé.", "Le Conquérant": "Le Saboteur. L'Hérétique mine l'effort de guerre de l'intérieur. La cinquième colonne, le traître qui ouvre les portes.", "L'Abomination": "L'Alliance Interdite. S'allier avec les monstres ou le Sepsis pour gagner en puissance. Devenir ce que l'on combat.", "Le Destructeur": "L'Anarchiste. \"Ni Dieu ni Maître\". Le but est le chaos pur, la destruction des structures sans plan de reconstruction.", "L'Élu": "Le Faux Prophète. Prétendre être un messie pour détourner les fidèles. Ou bien être le véritable élu rejeté par l'église officielle.", "Le Profanateur": "Le Blasphème. Insulter le sacré par pur plaisir ou rancœur. Profaner les temples et les symboles pour briser le moral.", "Le Protecteur": "L'Infiltré. L'ennemi est à l'intérieur. Le Protecteur échoue à voir que la menace vient du cœur du groupe.", "Le Visionnaire": "Le Radical. Une vision du futur qui exige de détruire le présent. Une utopie qui commence par un bain de sang.", "Le Fanatique": "La Guerre Sainte. Le conflit le plus violent. L'Hérétique et le Fanatique ne peuvent coexister : l'un doit mourir.", "Le Disciple": "La Mauvaise Influence. L'Hérétique séduit le Disciple et l'éloigne de son Mentor. La tentation de la facilité ou de la rébellion.", "Le Vertueux": "Le Procès. L'Hérétique face à ses juges. La confrontation entre la loi morale rigide et la liberté individuelle.", "Le Voyageur": "Le Vagabond Suspect. Celui qui apporte des idées étrangères et dangereuses. Le colporteur de rumeurs qui déstabilise les villages."}, "Le Conquérant": {"L'Aventurier": "L'Éclaireur. L'avant-garde de l'armée. L'Aventurier repère le terrain pour que le Conquérant puisse avancer ses troupes.", "Le Créateur": "L'Ingénieur de Siège. Construire des machines de guerre. La créativité au service de la destruction et de la prise de territoire.", "Le Mentor": "Le Maître d'Armes. L'entraînement rigoureux. La victoire se prépare bien avant la bataille grâce à la discipline enseignée.", "Le Martyr": "Le Soldat Inconnu. La chair à canon sacrifiée pour la gloire du Conquérant. La réalité sanglante de la victoire.", "Le Chef": "Le Généralissime. Le pouvoir politique et militaire réunis. Une dictature militaire ou un état de guerre permanent.", "Le Chercheur": "La Supériorité Technologique. Gagner grâce à de meilleures armes. La course à l'armement.", "Le Soigneur": "L'Hôpital de Campagne. Remettre les soldats sur pied pour qu'ils combattent à nouveau. La médecine de guerre.", "Le Traditionaliste": "La Guerre de Clan. Se battre pour l'honneur des ancêtres ou pour récupérer des terres historiques.", "Le Médiateur": "L'Ultimatum. \"Rendez-vous ou mourez\". La diplomatie armée. La négociation sous la menace directe.", "L'Ermite": "La Résistance. L'Ermite connaît le terrain et harcèle l'armée du Conquérant. La guérilla.", "L'Hérétique": "L'Insoumis. Celui qui refuse de plier le genou devant le vainqueur. La rébellion interne dans les territoires occupés.", "L'Abomination": "La Guerre Totale. Utiliser des armes terrifiantes (chimiques, biologiques, psychiques). La victoire à n'importe quel prix, même celui de son humanité.", "Le Destructeur": "Le Massacre. Il ne s'agit plus de conquérir, mais d'exterminer. Pas de prisonniers, terre brûlée.", "L'Élu": "Le Croisé. La guerre sainte. Conquérir au nom d'un dieu ou d'une destinée manifeste. La foi comme moteur de l'expansion.", "Le Profanateur": "Le Pilleur. La guerre pour le butin. Le Conquérant laisse ses troupes violer et voler après la victoire. La gloire salie.", "Le Protecteur": "Le Siège. La force inarrêtable (Conquérant) contre l'objet inamovible (Protecteur). L'attaque contre la défense.", "Le Visionnaire": "Le Nouvel Ordre. Conquérir pour unifier. Le but n'est pas la guerre, mais la paix impériale qui suivra. \"Si vis pacem, para bellum\".", "Le Fanatique": "Le Berserker. La fureur au combat. Des soldats qui ne connaissent pas la peur, drogués à la foi ou à la haine.", "Le Disciple": "L'Écuyer. Apprendre la guerre dans l'ombre du grand guerrier. Aspirer à devenir un héros militaire.", "Le Vertueux": "La Guerre Juste. Conviction que le combat est moralement nécessaire. Punir les \"méchants\". Le justicier armé.", "Le Voyageur": "L'Invasion. Une horde nomade qui déferle. La conquête ne vise pas à s'installer, mais à prendre et avancer."}, "L'Abomination": {"L'Aventurier": "La Rencontre. Tomber nez à nez avec l'horreur. L'aventure tourne au cauchemar. La fuite ou la mort.", "Le Créateur": "L'Art Macabre. Créer à partir de chair ou d'os. Une œuvre dérangeante qui reflète la folie de son auteur.", "Le Mentor": "La Mauvaise Éducation. Transmettre des traumatismes. L'Abomination est un Mentor abusif qui brise l'esprit de ses élèves.", "Le Martyr": "La Victime Consentante. Se laisser détruire par le monstre, par fascination ou désespoir. Le syndrome de Stockholm.", "Le Chef": "Le Règne de la Terreur. Un leader monstrueux ou fou. Le peuple obéit car la peur de la punition est absolue.", "Le Chercheur": "L'Expérience Ratée. La science a créé un monstre. Ou l'étude de l'Abomination contamine l'esprit du Chercheur.", "Le Soigneur": "La Mutation. Le soin qui dérape. Le corps guérit mais change. Le Sepsis qui s'installe dans la plaie.", "Le Traditionaliste": "Le Tabou. L'Abomination représente tout ce que la tradition interdit. La peur ancestrale du \"Dehors\".", "Le Médiateur": "L'Appât. Sacrifier quelqu'un pour calmer le monstre. Tenter de négocier avec une force qui ne comprend que la faim.", "L'Ermite": "L'Ensauvagement. À force de vivre seul, on perd son humanité. L'Ermite devient une bête.", "L'Hérétique": "Le Culte du Monstre. Vénérer l'Abomination comme un dieu nouveau. Voir la beauté dans l'horreur.", "Le Conquérant": "L'Arme Biologique. Utiliser des créatures ou des horreurs comme chiens de guerre. Lâcher la bête sur l'ennemi.", "Le Destructeur": "L'Apocalypse. Le chaos total. Le monstre détruit tout, sans but ni raison. La fin de toute vie.", "L'Élu": "L'Antéchrist. Une figure charismatique mais profondément maléfique ou corrompue. Le faux sauveur qui mène à la damnation.", "Le Profanateur": "La Torture. Le plaisir de faire souffrir. L'Abomination et le Profanateur s'allient pour le pire. La cruauté pure.", "Le Protecteur": "Le Cauchemar. Le Protecteur échoue. L'horreur a pénétré dans le sanctuaire. La peur pour ses proches.", "Le Visionnaire": "La Vision d'Horreur. Prévoir un avenir sombre et inéluctable. La folie qui vient de la connaissance du futur terrible.", "Le Fanatique": "La Chasse aux Sorcières. La paranoïa. Voir des abominations partout et brûler des innocents par peur de la contamination.", "Le Disciple": "La Corruption. L'innocence perdue. Le Disciple est touché par le mal et commence sa transformation.", "Le Vertueux": "L'Exorcisme. Le combat moral contre l'horreur. Tenter de purger le mal par la volonté et la foi, ou détruire le \"monstre\" sans pitié.", "Le Voyageur": "La Peste. L'Abomination se déplace. L'horreur qui voyage de ville en ville, contaminant tout sur son passage."}, "Le Destructeur": {"L'Aventurier": "La Marche à la Mort. Une expédition dont on ne revient pas. Aller au cœur du danger pour y mettre fin, quoi qu'il en coûte.", "Le Créateur": "L'Entropie. Le conflit éternel. Le Destructeur brise ce que le Créateur bâtit. Ou bien la destruction nécessaire pour laisser place au neuf.", "Le Mentor": "La Fin d'une Ère. Tuer le père. Rejeter les anciens enseignements pour se libérer. Briser la tradition pour avancer.", "Le Martyr": "Le Sacrifice Ultime. Se détruire soi-même pour emporter l'ennemi. L'explosion finale où tout disparaît, héros et monstres.", "Le Chef": "Le Coup d'État. Renverser le pouvoir par la force brute. L'anarchie remplace l'ordre. La chute d'un tyran ou d'un roi.", "Le Chercheur": "La Science Mortelle. Découvrir comment détruire le monde. L'arme nucléaire, le poison parfait. Le savoir au service de la mort.", "Le Soigneur": "L'Acharnement. Le Soigneur tente de sauver ce que le Destructeur condamne. Le combat contre l'inévitable déclin.", "Le Traditionaliste": "L'Iconoclasme. Briser les idoles et brûler les temples. Effacer le passé pour qu'il n'entrave plus le présent.", "Le Médiateur": "L'Échec des Mots. La violence éclate quand le dialogue s'arrête. Le Destructeur arrive quand le Médiateur a échoué.", "L'Ermite": "Le Survivant Solitaire. Celui qui reste après le cataclysme. L'Ermite contemple les ruines laissées par le Destructeur.", "L'Hérétique": "Le Chaos Pur. L'alliance du désordre et de la destruction. La révolte ne vise plus à changer le système, mais à l'annihiler totalement.", "Le Conquérant": "La Terre Brûlée. On ne conquiert pas pour régner, mais pour empêcher l'autre d'avoir. Détruire les ressources de l'ennemi.", "L'Abomination": "L'Exterminateur. Le seul moyen de traiter le monstre est de tout brûler autour de lui. La purification par le feu.", "L'Élu": "Le Fléau de Dieu. Se voir comme l'instrument divin de la colère. Punir le monde pour ses péchés par la destruction.", "Le Profanateur": "Le Vandalisme. Détruire par jalousie ou méchanceté gratuite. Le plaisir de gâcher ce qui est beau ou pur.", "Le Protecteur": "Le Siège Final. La force irrésistible contre l'objet inamovible. L'assaut désespéré contre le dernier bastion.", "Le Visionnaire": "La Tabula Rasa. Il faut détruire le monde actuel pour bâtir l'utopie. La révolution sanglante comme prélude au paradis.", "Le Fanatique": "La Guerre Totale. Détruire tout ce qui est différent. L'intolérance absolue qui mène au massacre des infidèles.", "Le Disciple": "La Perte d'Innocence. Voir ses idéaux brisés. Le Destructeur montre au Disciple la cruauté du monde réel.", "Le Vertueux": "Le Châtiment. La peine de mort. La destruction est justifiée par la morale. Exécuter le coupable sans remords.", "Le Voyageur": "La Poursuite. La destruction est sur vos talons. Fuir une menace qui ravage tout derrière vous (une tempête, une horde)."}, "L'Élu": {"L'Aventurier": "Le Héros. Le protagoniste classique. Celui qui part à l'aventure parce que c'est son destin. La quête initiatique.", "Le Créateur": "L'Architecte Divin. Construire un monde à son image. L'Élu inspire la création de monuments à sa propre gloire.", "Le Mentor": "L'Enfant Prodige. L'élève dépasse le maître car il a un don inné. Le Mentor guide celui qui est destiné à de grandes choses.", "Le Martyr": "Le Messie. Souffrir pour sauver son peuple. La destinée de l'Élu est tragique : il doit mourir pour que les autres vivent.", "Le Chef": "Le Roi Légitime. Le pouvoir ne vient pas de la force, mais du droit divin ou du sang. L'autorité naturelle incontestée.", "Le Chercheur": "La Révélation. Découvrir une vérité qui change le monde. L'Élu n'étudie pas, il sait ou il trouve par intuition géniale.", "Le Soigneur": "Le Thaumaturge. Guérir par apposition des mains ou par la foi. Le charisme qui apaise et redonne force.", "Le Traditionaliste": "La Prophétie Réalisée. L'Élu est celui qu'on attendait depuis des siècles. Le respect scrupuleux des écritures anciennes.", "Le Médiateur": "Le Rassembleur. Unifier les clans divisés par sa seule présence. L'Élu apporte la paix car tout le monde l'écoute.", "L'Ermite": "La Traversée du Désert. L'Élu doit s'isoler pour comprendre sa mission avant de revenir guider le monde.", "L'Hérétique": "Le Faux Prophète. Une figure charismatique qui mène les foules à leur perte ou qui prêche une vérité contraire au dogme.", "Le Conquérant": "Le Grand Unificateur. Conquérir le monde pour \"son bien\". L'ambition impériale justifiée par une mission supérieure.", "L'Abomination": "La Tentation. Le destin de l'Élu est lié aux forces obscures. Lutter contre sa propre nature monstrueuse ou son côté sombre.", "Le Destructeur": "L'Annonciateur. Le prophète de l'apocalypse. L'Élu est venu pour fermer le livre de l'histoire, pas pour en écrire un nouveau.", "Le Profanateur": "L'Imposteur. Quelqu'un qui se fait passer pour l'Élu. Voler la gloire et abuser de la confiance des fidèles.", "Le Protecteur": "Le Garde du Corps. L'Élu est précieux et fragile. Il faut le protéger à tout prix jusqu'à ce qu'il accomplisse son destin.", "Le Visionnaire": "Le Guide Spirituel. Montrer la voie vers un futur radieux. L'Élu incarne l'espoir d'un lendemain meilleur.", "Le Fanatique": "Le Culte. L'admiration vire à l'obsession. Les disciples de l'Élu sont prêts à tuer pour lui. Le danger de l'idolâtrie.", "Le Disciple": "Les Apôtres. Ceux qui suivent l'Élu partout, boivent ses paroles et écriront sa légende.", "Le Vertueux": "Le Saint. L'Élu est un modèle de perfection morale. Il juge les vivants et incarne la justice divine.", "Le Voyageur": "Le Missionnaire. Porter la parole divine ou l'espoir dans les contrées lointaines. L'Élu ne s'arrête jamais."}, "Le Profanateur": {"L'Aventurier": "Le Piège. L'aventure est truquée. Le Profanateur envoie l'Aventurier sur une fausse piste ou dans une embuscade par malice.", "Le Créateur": "Le Sabotage. Détruire l'œuvre d'autrui parce qu'on est incapable de créer soi-même. Le vandalisme artistique ou industriel.", "Le Mentor": "La Calomnie. Ruiner la réputation d'un sage. Répandre des rumeurs pour que l'élève doute du maître.", "Le Martyr": "L'Humiliation. Se moquer de la souffrance d'autrui. Profiter du sacrifice de quelqu'un sans aucune reconnaissance. Cracher sur la tombe.", "Le Chef": "L'Usurpateur. Comploter dans l'ombre pour prendre la place du Chef, non par compétence, mais par envie.", "Le Chercheur": "Le Vol de Brevet. S'attribuer la découverte d'un autre. Copier le travail et présenter les résultats comme les siens.", "Le Soigneur": "L'Empoisonnement. Remplacer le remède par du poison. Faire souffrir le patient sous couvert de le soigner. Le sadisme médical.", "Le Traditionaliste": "Le Sacrilège. Violer les lieux saints, briser les tabous juste pour choquer les anciens. Souiller la mémoire.", "Le Médiateur": "La Zizanie. Faire échouer les négociations en mentant aux deux parties. Se réjouir du conflit qu'on a provoqué.", "L'Ermite": "Le Harcèlement. Ne pas laisser l'autre en paix. Traquer celui qui veut être seul pour le tourmenter.", "L'Hérétique": "L'Opportunisme. Rejoindre la rébellion non par conviction, mais pour le plaisir de nuire à l'ordre établi et de piller.", "Le Conquérant": "Le Pillard. Suivre l'armée pour voler les cadavres et violer les vaincus. La guerre sans honneur.", "L'Abomination": "La Corruption Morale. Devenir un monstre par choix. Le Profanateur s'allie à l'horreur car elle lui donne le pouvoir de nuire.", "Le Destructeur": "La Haine Pure. L'alliance de la méchanceté et de la puissance. Vouloir détruire le monde parce qu'il ne nous a pas donné ce qu'on voulait.", "L'Élu": "Le Jaloux. Détester le héros. Être l'antagoniste qui veut prouver que l'Élu n'est qu'une fraude. Salieri face à Mozart.", "Le Protecteur": "L'Infiltration. Entrer dans la place forte par ruse pour ouvrir les portes à l'ennemi ou voler le trésor protégé.", "Le Visionnaire": "Le Cynisme. Briser les rêves. Dire à tout le monde que l'espoir est vain et que le futur sera sombre, juste pour les décourager.", "Le Fanatique": "L'Hypocrisie. Se prétendre dévot pour manipuler les croyants. Utiliser la religion pour assouvir ses bas instincts.", "Le Disciple": "Le Mauvais Compagnon. Celui qui entraîne l'élève naïf vers le vice et la paresse.", "Le Vertueux": "Le Vice. Le Profanateur incarne tout ce que le Vertueux déteste. Un duel entre la morale rigide et l'amoralité totale.", "Le Voyageur": "Le Bandit. Attendre les voyageurs au coin du bois pour les détrousser. Rendre les routes dangereuses."}, "Le Protecteur": {"L'Aventurier": "L'Escorte. Le Protecteur accompagne l'Aventurier pour qu'il revienne vivant. Le duo classique : le mage fragile et le guerrier tank.", "Le Créateur": "La Forteresse. Construire des murs. Le Créateur conçoit les défenses, le Protecteur les tient. Sécuriser l'atelier.", "Le Mentor": "Le Gardien du Savoir. Protéger les livres et les maîtres. Empêcher que la connaissance ne soit détruite par les barbares.", "Le Martyr": "Le Sacrifice Défensif. Mourir pour protéger la porte. \"Vous ne passerez pas !\" Le Protecteur donne sa vie pour les siens.", "Le Chef": "La Garde Royale. La loyauté absolue envers le dirigeant. Protéger l'ordre et la hiérarchie contre toute menace.", "Le Chercheur": "Le Confinement. Empêcher quelque chose de sortir. Protéger le monde d'une découverte dangereuse ou d'un virus étudié en labo.", "Le Soigneur": "Le Sanctuaire. Un lieu sûr où l'on peut guérir. Le Protecteur garantit que personne n'attaquera l'hôpital ou les blessés.", "Le Traditionaliste": "Le Conservatisme. Protéger le mode de vie. Refuser le changement pour garder l'identité du clan intacte.", "Le Médiateur": "Le Casque Bleu. Une force armée qui s'interpose pour maintenir la paix. Protéger les civils des deux camps.", "L'Ermite": "La Cachette. Protéger le secret de la retraite. Aider quelqu'un à disparaître et veiller à ce qu'on ne le retrouve pas.", "L'Hérétique": "L'Asile. Protéger le persécuté. Offrir refuge à celui que la société veut tuer, par principe d'hospitalité.", "Le Conquérant": "La Résistance. Défendre sa terre contre l'envahisseur. Tenir le siège face à une armée supérieure en nombre.", "L'Abomination": "Le Rempart. Être la dernière ligne de défense entre l'humanité et l'horreur absolue. La Garde de Nuit.", "Le Destructeur": "L'Échec. Le Protecteur est brisé. La défense cède face à la puissance d'anéantissement. La fin de la sécurité.", "L'Élu": "Le Paladin. Vouer son épée à une cause sainte. Protéger l'Élu car il est l'espoir du monde.", "Le Profanateur": "Le Traître. Le danger vient de l'intérieur. Le Protecteur ne voit pas que celui qu'il protège est corrompu, ou il est trahi par un \"ami\".", "Le Visionnaire": "Préserver l'Avenir. Protéger les enfants ou les graines qui feront le monde de demain. Sacrifier le présent pour le futur.", "Le Fanatique": "La Police des Mœurs. Protéger la vertu par la force. Surveiller les comportements pour empêcher le péché.", "Le Disciple": "Le Parrain. Prendre un jeune sous son aile pour lui éviter les ennuis. Une protection bienveillante et éducative.", "Le Vertueux": "Le Justicier. Protéger les innocents et punir les coupables. La loi est le bouclier des faibles.", "Le Voyageur": "Le Convoi. Protéger une caravane sur la route. Assurer la sécurité du transport de marchandises ou de personnes."}, "Le Visionnaire": {"L'Aventurier": "L'Explorateur. Partir vers une terre promise. Le Visionnaire a vu un lieu meilleur sur la carte, l'Aventurier y va.", "Le Créateur": "L'Inventeur Génial. Concevoir la technologie de demain. Une idée révolutionnaire qui prend forme grâce à l'ingénierie.", "Le Mentor": "La Réforme. Changer l'enseignement. Le Visionnaire modernise les vieilles leçons pour les adapter au monde qui vient.", "Le Martyr": "Le Précurseur. Être en avance sur son temps et en souffrir. Être moqué ou rejeté parce qu'on voit ce que les autres ne voient pas encore.", "Le Chef": "Le Planificateur. Un leader qui a une vision à long terme. Ne pas gérer le quotidien, mais tracer la route pour les dix prochaines années.", "Le Chercheur": "La Science-Fiction. Imaginer l'impossible pour que la science tente de l'atteindre. L'inspiration théorique.", "Le Soigneur": "La Santé Future. Éradiquer une maladie pour toujours. Travailler sur la prévention et l'hygiène plutôt que sur le soin immédiat.", "Le Traditionaliste": "Le Choc Culturel. Le conflit entre \"c'était mieux avant\" et \"demain sera mieux\". Le passé contre le futur.", "Le Médiateur": "L'Union. Rêver d'un monde sans frontières. Le Visionnaire propose une paix universelle que le Médiateur tente de concrétiser.", "L'Ermite": "La Prophétie. Voir l'avenir dans les signes ou les rêves. Une vision mystique reçue dans l'isolement.", "L'Hérétique": "L'Utopiste Radical. Vouloir détruire la société actuelle pour en reconstruire une parfaite. La fin justifie les moyens.", "Le Conquérant": "L'Empire Millénaire. Conquérir pour bâtir une civilisation éternelle. L'ambition dépasse la vie d'un seul homme.", "L'Abomination": "La Dystopie. Prévoir un avenir cauchemardesque. Voir la corruption du monde et savoir qu'elle est inéluctable.", "Le Destructeur": "L'Apocalypse Révélée. Savoir quand et comment tout va finir. Le compte à rebours a commencé.", "L'Élu": "Le Messianisme. Annoncer la venue d'un sauveur. Préparer le monde à l'arrivée de celui qui changera tout.", "Le Profanateur": "Le Pessimisme. Le Visionnaire voit les failles et prédit l'échec. Casser le moral en annonçant le pire.", "Le Protecteur": "La Prévention. \"Mieux vaut prévenir que guérir\". Anticiper les menaces pour s'en protéger avant qu'elles n'arrivent.", "Le Fanatique": "Le Dogme Nouveau. Créer une nouvelle religion. Une vision si puissante qu'elle rend les gens fous de foi.", "Le Disciple": "L'École du Futur. Former la jeunesse pour un monde qui n'existe pas encore. Parier sur la nouvelle génération.", "Le Vertueux": "L'Idéaliste. Rêver d'un monde parfaitement juste. Juger le présent à l'aune d'un idéal impossible à atteindre.", "Le Voyageur": "La Migration. Sentir que le vent tourne et qu'il faut partir. Guider le peuple vers une nouvelle terre d'accueil."}, "Le Fanatique": {"L'Aventurier": "La Quête Sacrée. Partir à l'aventure non par curiosité, mais par mission divine. Traverser les enfers pour prouver sa foi.", "Le Créateur": "L'Idole. Construire des temples, des statues ou des objets de culte. L'art et la technique sont entièrement soumis à la religion.", "Le Mentor": "L'Endoctrinement. Le Fanatique n'enseigne pas le doute, il impose la vérité. Le lavage de cerveau de la nouvelle génération.", "Le Martyr": "Le Kamikaze. L'arme ultime de la foi. Le Fanatique pousse le Martyr à se sacrifier pour détruire les ennemis du culte.", "Le Chef": "La Théocratie. Le pouvoir religieux domine le politique. Les lois humaines sont remplacées par les lois divines impitoyables.", "Le Chercheur": "Le Dogme. Refuser la science si elle contredit les écritures. Brûler les livres ou tordre les faits pour qu'ils collent à la croyance.", "Le Soigneur": "La Foi Guérisseuse. Penser que la prière suffit, ou soigner l'âme avant le corps. Purifier le \"péché\" de la maladie par la douleur.", "Le Traditionaliste": "Le Fondamentalisme. L'alliance la plus rigide. Refus total de toute évolution. Vivre exactement comme les textes sacrés le dictent.", "Le Médiateur": "Le Prosélytisme. Convaincre l'autre par la parole. Le Fanatique utilise le Médiateur pour convertir les infidèles sans violence immédiate.", "L'Ermite": "Le Moine. Se retirer du monde pour prier sans distraction. La foi vécue dans l'ascèse et le silence absolu.", "L'Hérétique": "L'Inquisition. La guerre totale. Le Fanatique traque l'Hérétique sans relâche pour le brûler. Le choc des croyances.", "Le Conquérant": "La Guerre Sainte. Convertir par l'épée. Envahir les terres voisines pour y imposer son dieu ou sa cause.", "L'Abomination": "Le Démon. Le Fanatique voit le mal surnaturel partout. Combat spirituel contre une horreur bien réelle.", "Le Destructeur": "Le Jugement Dernier. Croire que la fin du monde est la volonté divine et qu'il faut l'accélérer pour purifier la Terre.", "L'Élu": "Le Culte de la Personnalité. Le Fanatique a trouvé son messie. Dévotion aveugle et totale envers un individu charismatique.", "Le Profanateur": "Le Tartuffe. Utiliser la religion pour cacher ses vices. Le Fanatique est manipulé ou devient lui-même un hypocrite cruel.", "Le Protecteur": "Le Templier. Le guerrier saint. Protéger les lieux sacrés et les pèlerins avec une ferveur meurtrière.", "Le Visionnaire": "La Nouvelle Jérusalem. Rêver d'un futur où tout le monde croira en la même chose. L'utopie religieuse totalitaire.", "Le Disciple": "Le Novice. La recrue idéale. Le Fanatique forme le Disciple à obéir sans poser de questions et à servir la cause.", "Le Vertueux": "Le Puritain. L'obsession de la pureté morale. Condamner le moindre écart de conduite avec une sévérité extrême.", "Le Voyageur": "Le Pèlerin. Voyager pour atteindre un lieu saint. La route est une épreuve de foi, une marche pénitentielle."}, "Le Disciple": {"L'Aventurier": "Le Compagnon. Suivre le héros dans ses aventures pour apprendre la vie \"à la dure\". Le sidekick fidèle.", "Le Créateur": "L'Apprenti. Travailler dans l'ombre du maître artisan. Apprendre les techniques en balayant l'atelier et en observant.", "Le Mentor": "L'Élève Modèle. La relation parfaite. Le Disciple boit les paroles du Mentor. L'absorption totale du savoir.", "Le Martyr": "Le Dévouement. Servir quelqu'un jusqu'au sacrifice. Le Disciple aime tellement son maître qu'il est prêt à mourir pour lui.", "Le Chef": "Le Lieutenant. Apprendre le commandement en servant un leader. Exécuter les ordres pour comprendre comment fonctionne le pouvoir.", "Le Chercheur": "L'Assistant. Aider aux expériences, prendre des notes. Le Disciple fait le sale boulot pour que le Chercheur fasse les découvertes.", "Le Soigneur": "L'Interne. Apprendre à soigner en regardant la mort en face. Porter la trousse de secours et assister aux opérations.", "Le Traditionaliste": "L'Initié. Passer les rites de passage pour devenir un membre adulte du clan. Apprendre les coutumes par cœur.", "Le Médiateur": "Le Messager. Porter la parole d'un autre. Apprendre la diplomatie en observant les négociations silencieusement.", "L'Ermite": "La Quête de Sagesse. Aller chercher le maître là où il se cache. Le test de persévérance pour avoir le droit d'apprendre.", "L'Hérétique": "L'Influence Corruptrice. Le Disciple est séduit par des idées dangereuses. La rébellion adolescente contre le père spirituel.", "Le Conquérant": "L'Écuyer. Porter les armes du chevalier. Apprendre la guerre et la violence en suivant l'armée.", "L'Abomination": "La Perte d'Innocence. Le Disciple découvre l'horreur du monde trop tôt. Un traumatisme qui le changera à jamais.", "Le Destructeur": "La Mauvaise Voie. Suivre quelqu'un qui mène au néant. Apprendre à détruire plutôt qu'à construire.", "L'Élu": "L'Apôtre. Le premier d'une longue liste de fidèles. Le Disciple a pour mission de témoigner de la grandeur de l'Élu.", "Le Profanateur": "La Victime. Le Disciple est exploité, humilié ou manipulé par un faux maître cruel.", "Le Protecteur": "Le Pupille. Le Disciple est celui qu'on protège. Il est l'avenir du clan, trop précieux pour être exposé au danger.", "Le Visionnaire": "L'Héritier. Le Visionnaire prépare le Disciple à construire le monde de demain. \"Tout ceci sera à toi un jour\".", "Le Fanatique": "Le Converti. Le Disciple abandonne son esprit critique pour embrasser une foi aveugle. Devenir un instrument de la secte.", "Le Vertueux": "L'Éducation Stricte. Apprendre la discipline et la morale. Le Disciple est dressé plus qu'il n'est éduqué.", "Le Voyageur": "Le Tour du Monde. Le voyage initiatique. Partir sur les routes pour compléter sa formation avant de revenir (ou pas)."}, "Le Vertueux": {"L'Aventurier": "Le Justicier Errant. Parcourir le monde pour redresser les torts. Le shérif solitaire qui apporte la loi dans les zones sauvages.", "Le Créateur": "La Norme. Imposer des règles strictes à la création. L'art doit être moral et utile. La censure de ce qui est jugé \"déviant\".", "Le Mentor": "L'Éthique. Enseigner le bien et le mal avant d'enseigner la technique. La conscience morale du groupe.", "Le Martyr": "La Pénitence. Accepter la souffrance comme juste châtiment de ses fautes. Le Vertueux s'inflige des épreuves pour rester pur.", "Le Chef": "Le Législateur. Écrire les lois que le Chef fera appliquer. Le pouvoir judiciaire qui équilibre ou contraint le pouvoir exécutif.", "Le Chercheur": "La Bioéthique. Mettre des limites à la science. \"Science sans conscience n'est que ruine de l'âme\". Interdire certaines recherches.", "Le Soigneur": "Le Choix Moral. Décider qui mérite d'être sauvé. Refuser de soigner un meurtrier ou un ennemi par principe.", "Le Traditionaliste": "Le Code d'Honneur. La morale vient des ancêtres. Respecter les vieilles lois à la lettre, même si elles sont cruelles.", "Le Médiateur": "L'Arbitre. Trancher un conflit de manière impartiale. Non pas chercher un compromis mou, mais dire qui a raison et qui a tort.", "L'Ermite": "Le Juge Suprême. Se retirer du monde pour ne pas être corrompu par lui. Juger l'humanité depuis sa tour d'ivoire.", "L'Hérétique": "Le Procès. La confrontation inévitable. Le Vertueux doit condamner l'Hérétique pour préserver l'ordre moral.", "Le Conquérant": "La Guerre Juste. Conviction que notre camp est le Bien et que l'ennemi est le Mal. La croisade morale.", "L'Abomination": "L'Exorciste. Combattre le monstre non seulement physiquement, mais spirituellement. Rejeter la corruption du corps et de l'âme.", "Le Destructeur": "L'Exécuteur. La peine capitale. La destruction est un acte de justice nécessaire pour purger le monde du vice.", "L'Élu": "Le Saint. Une figure de perfection morale qui inspire par son exemple. L'autorité vient de la vertu, pas de la force.", "Le Profanateur": "Le Vice. L'ennemi juré. Le Profanateur cherche à corrompre le Vertueux, à le faire tomber de son piédestal.", "Le Protecteur": "La Police. Protéger les innocents contre les criminels. Maintenir l'ordre public par la force si nécessaire.", "Le Visionnaire": "L'Utopie Morale. Rêver d'une société parfaite où le crime n'existe plus. Un monde ordonné et juste, peut-être trop.", "Le Fanatique": "L'Intolérance. Quand la vertu devient haine. Punir tout ce qui est différent au nom de la \"pureté\".", "Le Disciple": "La Discipline. Élever un enfant dans le droit chemin. Une éducation rigide et sans tendresse, mais structurante.", "Le Voyageur": "Le Juge Itinérant. Aller de ville en ville pour tenir audience. Apporter la loi là où il n'y en a pas."}, "Le Voyageur": {"L'Aventurier": "Les Nomades. Vivre sur la route par choix et par goût. Ne jamais dormir deux fois au même endroit. La liberté totale.", "Le Créateur": "Le Bricoleur Itinérant. Réparer et créer avec ce qu'on trouve sur le chemin. Le marchand qui vend des objets exotiques.", "Le Mentor": "Le Sage Errant. Un maître qui n'a pas d'école. Il enseigne au gré des rencontres, semant le savoir aux quatre vents.", "Le Martyr": "L'Exil. Être chassé de chez soi. Le voyage est une souffrance, une fuite perpétuelle sans espoir de retour.", "Le Chef": "Le Chef de Caravane. Diriger une communauté mobile. La gestion logistique d'un groupe en mouvement constant.", "Le Chercheur": "L'Explorateur. Cartographier le monde. Aller voir ce qu'il y a derrière l'horizon pour le rapporter à la civilisation.", "Le Soigneur": "Le Médecin Volant. Apporter des soins aux communautés isolées. Transporter des médicaments d'une ville à l'autre.", "Le Traditionaliste": "Les Gitans / Le Peuple Voyageur. Un clan qui a pour tradition de ne jamais se fixer. La route est leur maison ancestrale.", "Le Médiateur": "L'Ambassadeur. Faire le lien entre des nations lointaines. Le Voyageur permet le dialogue car il connaît les coutumes de tous.", "L'Ermite": "La Rencontre. L'Ermite est un point fixe, le Voyageur passe. Un échange bref mais intense avant la séparation.", "L'Hérétique": "Le Colporteur. Répandre des nouvelles et des idées séditieuses de ville en ville. Le virus de la révolte voyage avec lui.", "Le Conquérant": "La Horde. Une armée en mouvement. L'invasion barbare qui ne cherche pas à s'installer mais à piller et avancer.", "L'Abomination": "Le Vecteur. Transporter le Sepsis ou une malédiction sans le savoir. Le Voyageur amène la peste dans la ville saine.", "Le Destructeur": "La Fuite. Courir pour sa vie. Le danger est juste derrière. Le Voyageur ne s'arrête que quand il est épuisé.", "L'Élu": "Le Missionnaire. Parcourir le monde pour prêcher la bonne parole. Répandre la foi aux confins de la terre connue.", "Le Profanateur": "Le Bandit de Grand Chemin. Tendre des embuscades aux voyageurs. La route est dangereuse et pleine de prédateurs.", "Le Protecteur": "L'Escorte. Assurer la sécurité du convoi. Protéger les marchandises et les personnes contre les dangers de la route.", "Le Visionnaire": "L'Exode. Guider le peuple vers une terre promise. Le voyage a un but précis : fonder une nouvelle société ailleurs.", "Le Fanatique": "Le Pèlerinage. Une marche sacrée vers un lieu de culte lointain. Le voyage est un acte de dévotion.", "Le Disciple": "Le Compagnonnage. Partir sur les routes pour apprendre son métier et découvrir le monde avant de s'installer.", "Le Vertueux": "Le Marshal. Traquer un criminel à travers le pays. La justice qui poursuit le coupable peu importe la distance."}}};